{
  "claim": "For non-headline hyperscaler spot series outside the 14-day gate, widening the current forecast's log intervals by 25% will reduce pinball loss by better representing the size of subsequent median changes.",
  "mechanism": "The hypothesis is that spot-offer repricing and changes in offer availability can move the middle-ranked offers enough to produce median jumps beyond the blend's current tails. Coverage of 0.76 in the ungated hyperscaler-spot slice motivates widening both tails while preserving the current q50; the earlier rejected centring experiment does not establish that the last value is a better centre.",
  "spec": {
    "when": {
      "all": [
        {
          "fact": "cls",
          "op": "==",
          "value": "hyperscaler_spot"
        },
        {
          "fact": "gate14",
          "op": "==",
          "value": false
        },
        {
          "fact": "in37",
          "op": "==",
          "value": false
        }
      ]
    },
    "do": {
      "action": "scale_width",
      "lo": 1.25,
      "hi": 1.25
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least five series change, headline pooled skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show a rise.",
  "prior_ids_used": [
    "auto-c0918-pastdev-wf-i6",
    "auto-c0918-pastdev-wf-i4"
  ],
  "expects": "I expect a modest pooled-skill improvement and increased coverage in the affected slice, with headline forecasts unchanged. The supplied aggregates do not establish whether the non-headline subset is undercovered or whether improvements will satisfy both temporal halves and the bootstrap requirement."
}
